import { useContext, useEffect, useState } from "react";
import {
    Chart as ChartJs,
    ArcElement,
    Tooltip,
    Legend,
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    PointElement,
    LineElement
} from "chart.js";
import { Bar, Pie, Line } from 'react-chartjs-2';
import { Context } from "./usecontext";
import { useNavigate } from "react-router-dom";
import Swal from "sweetalert2";

ChartJs.register(
    CategoryScale,
    LinearScale,
    BarElement,
    LineElement,
    ArcElement,
    PointElement,
    Tooltip,
    Legend,
    Title
);

// Reusable Pagination Component
const Pagination = ({ totalItems, itemsPerPage, currentPage, onPageChange, onPerPageChange }) => {
    const totalPages = Math.ceil(totalItems / itemsPerPage) || 1;
    const startItem = totalItems === 0 ? 0 : (currentPage - 1) * itemsPerPage + 1;
    const endItem = Math.min(currentPage * itemsPerPage, totalItems);

    const getPageNumbers = () => {
        const pages = [];
        const maxPagesToShow = 5;
        let startPage = Math.max(1, currentPage - Math.floor(maxPagesToShow / 2));
        let endPage = Math.min(totalPages, startPage + maxPagesToShow - 1);

        if (endPage - startPage + 1 < maxPagesToShow) {
            startPage = Math.max(1, endPage - maxPagesToShow + 1);
        }

        for (let i = startPage; i <= endPage; i++) {
            pages.push(i);
        }
        return pages;
    };

    return (
        <div className="d-flex flex-wrap justify-content-between align-items-center gap-3 mt-3 pt-3 border-top">
            <div className="text-muted small">
                Showing <strong className="text-dark">{startItem}</strong> to <strong className="text-dark">{endItem}</strong> of <strong className="text-dark">{totalItems}</strong> entries
            </div>

            <div className="d-flex align-items-center gap-3">
                <div className="d-flex align-items-center gap-2">
                    <span className="small text-muted text-nowrap">Per page:</span>
                    <select
                        className="form-select form-select-sm"
                        style={{ width: "75px" }}
                        value={itemsPerPage}
                        onChange={(e) => {
                            onPerPageChange(Number(e.target.value));
                            onPageChange(1);
                        }}
                    >
                        <option value={5}>5</option>
                        <option value={10}>10</option>
                        <option value={20}>20</option>
                        <option value={50}>50</option>
                    </select>
                </div>

                <nav aria-label="Table navigation">
                    <ul className="pagination pagination-sm mb-0">
                        <li className={`page-item ${currentPage === 1 ? 'disabled' : ''}`}>
                            <button className="page-link" onClick={() => onPageChange(1)} aria-label="First">
                                &laquo;&laquo;
                            </button>
                        </li>
                        <li className={`page-item ${currentPage === 1 ? 'disabled' : ''}`}>
                            <button className="page-link" onClick={() => onPageChange(currentPage - 1)} aria-label="Previous">
                                &laquo;
                            </button>
                        </li>

                        {getPageNumbers().map(p => (
                            <li key={p} className={`page-item ${currentPage === p ? 'active' : ''}`}>
                                <button className="page-link" onClick={() => onPageChange(p)}>
                                    {p}
                                </button>
                            </li>
                        ))}

                        <li className={`page-item ${currentPage === totalPages ? 'disabled' : ''}`}>
                            <button className="page-link" onClick={() => onPageChange(currentPage + 1)} aria-label="Next">
                                &raquo;
                            </button>
                        </li>
                        <li className={`page-item ${currentPage === totalPages ? 'disabled' : ''}`}>
                            <button className="page-link" onClick={() => onPageChange(totalPages)} aria-label="Last">
                                &raquo;&raquo;
                            </button>
                        </li>
                    </ul>
                </nav>
            </div>
        </div>
    );
};

export const Dashboard = () => {
    const [d, setd] = useState([]);
    const [order, setorderdata] = useState([]);
    const [users, setuser] = useState(0);
    const [length, setlength] = useState(0);
    const [totalorder, settotalorder] = useState(0);
    const [brand, setbrand] = useState(0);
    const [prolength, setprolength] = useState(0);
    const [totaladmin, setadmin] = useState(0);
    const [ondelivery, setondelivery] = useState(0);
    const [bycredit, setcredit] = useState(0);
    const [vdata, setvdata] = useState([]);

    // Per-row state storage
    const [pendingRoles, setPendingRoles] = useState({});
    const [pendingStatuses, setPendingStatuses] = useState({});
    const [pendingVendorStatuses, setPendingVendorStatuses] = useState({});

    // Pagination & Search States
    // Orders Pagination
    const [orderSearch, setOrderSearch] = useState("");
    const [orderPaymentFilter, setOrderPaymentFilter] = useState("all");
    const [orderPage, setOrderPage] = useState(1);
    const [orderPerPage, setOrderPerPage] = useState(5);

    // Users Pagination
    const [userSearch, setUserSearch] = useState("");
    const [userTypeFilter, setUserTypeFilter] = useState("all");
    const [userStatusFilter, setUserStatusFilter] = useState("all");
    const [userPage, setUserPage] = useState(1);
    const [userPerPage, setUserPerPage] = useState(5);

    // Vendor Pagination
    const [vendorSearch, setVendorSearch] = useState("");
    const [vendorStatusFilter, setVendorStatusFilter] = useState("all");
    const [vendorPage, setVendorPage] = useState(1);
    const [vendorPerPage, setVendorPerPage] = useState(5);

    const { utype } = useContext(Context);
    const navigate = useNavigate();

    const [monthlyData, setMonthlyData] = useState({
        labels: [],
        datasets: []
    });

    useEffect(() => {
        fetch("https://elcto-1.onrender.com/api/sales/monthly")
            .then(res => res.json())
            .then(data => {
                if (data && data.labels) {
                    setMonthlyData({
                        labels: data.labels,
                        datasets: [
                            {
                                label: "Monthly Sales (₹)",
                                data: data.values,
                                borderColor: "#0d6efd",
                                backgroundColor: "rgba(13, 110, 253, 0.1)",
                                fill: true,
                                tension: 0.3
                            }
                        ]
                    });
                }
            })
            .catch(err => console.error("Error loading monthly sales:", err));
    }, []);

    useEffect(() => {
        show();
        show2();
        show3();
        show4();
        show5();
        show6();
    }, []);

    const show = async () => {
        try {
            const result = await fetch("https://elcto-1.onrender.com/api/users", { method: "get" });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    setd(res.data);
                    setuser(res.data.length);
                    const admins = res.data.filter((a) => a.UserType === "admin");
                    setadmin(admins.length);
                }
            }
        } catch (err) {
            console.error("Error fetching users:", err);
        }
    };

    const show2 = async () => {
        try {
            const result = await fetch("https://elcto-1.onrender.com/api/getcategory", { method: "get" });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    setlength(res.data.length);
                }
            }
        } catch (err) {
            console.error("Error fetching categories:", err);
        }
    };

    const show3 = async () => {
        try {
            const result = await fetch("https://elcto-1.onrender.com/api/getproduct", { method: "get" });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    setprolength(res.data.length);
                }
            }
        } catch (err) {
            console.error("Error fetching products:", err);
        }
    };

    const show4 = async () => {
        try {
            const result = await fetch("https://elcto-1.onrender.com/api/showbrand", { method: "get" });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    setbrand(res.data.length);
                }
            }
        } catch (err) {
            console.error("Error fetching brands:", err);
        }
    };

    const show5 = async () => {
        try {
            const result = await fetch("https://elcto-1.onrender.com/api/orderdata", { method: "get" });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    setorderdata(res.data);
                    settotalorder(res.data.length);
                    const bycash = res.data.filter((a) => a.Payment === "Cash on Delivery");
                    const bycard = res.data.filter((a) => a.Payment === "Credit Card");
                    setondelivery(bycash.length);
                    setcredit(bycard.length);
                }
            }
        } catch (err) {
            console.error("Error fetching orders:", err);
        }
    };

    const show6 = async () => {
        try {
            const result = await fetch("https://elcto-1.onrender.com/api/vendordata", { method: "get" });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    setvdata(res.data);
                }
            }
        } catch (err) {
            console.error("Error fetching vendors:", err);
        }
    };

    // User Role Change Handler
    const handleUserRoleChange = async (userId) => {
        const selectedRole = pendingRoles[userId];
        if (!selectedRole) {
            Swal.fire("Info", "Please select a role first.", "info");
            return;
        }

        const confirm = await Swal.fire({
            title: "Confirm Role Update",
            text: `Are you sure you want to change user role to "${selectedRole}"?`,
            icon: "question",
            showCancelButton: true,
            confirmButtonColor: "#0d6efd",
            confirmButtonText: "Yes, Update"
        });

        if (!confirm.isConfirmed) return;

        try {
            const result = await fetch(`https://elcto-1.onrender.com/api/makeadmin/${userId}`, {
                method: "put",
                body: JSON.stringify({ ad: selectedRole }),
                headers: { "Content-type": "application/json;charset=UTF-8" }
            });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    Swal.fire({
                        title: "Updated!",
                        text: "User type changed successfully",
                        icon: "success",
                        timer: 1500,
                        showConfirmButton: false
                    });
                    show();
                } else {
                    Swal.fire("Error", "Role modification failed", "error");
                }
            }
        } catch (err) {
            Swal.fire("Error", "Network error updating role", "error");
        }
    };

    // User Status Change Handler
    const handleUserStatusChange = async (userId) => {
        const selectedStatus = pendingStatuses[userId];
        if (!selectedStatus) {
            Swal.fire("Info", "Please select a status first.", "info");
            return;
        }

        const confirm = await Swal.fire({
            title: "Confirm Status Change",
            text: `Are you sure you want to change user status to "${selectedStatus}"?`,
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#0d6efd",
            confirmButtonText: "Yes, Change"
        });

        if (!confirm.isConfirmed) return;

        try {
            const result = await fetch(`https://elcto-1.onrender.com/api/changestatus/${userId}`, {
                method: "put",
                body: JSON.stringify({ status: selectedStatus }),
                headers: { "Content-type": "application/json;charset=UTF-8" }
            });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    Swal.fire({
                        title: "Updated!",
                        text: "User status changed successfully",
                        icon: "success",
                        timer: 1500,
                        showConfirmButton: false
                    });
                    show();
                } else {
                    Swal.fire("Error", "Status update failed", "error");
                }
            }
        } catch (err) {
            Swal.fire("Error", "Network error updating status", "error");
        }
    };

    // Vendor Approval Handler
    const approval = async (id) => {
        const selectedStatus = pendingVendorStatuses[id];
        if (!selectedStatus) {
            Swal.fire("Info", "Please select an approval status first.", "info");
            return;
        }

        const confirm = await Swal.fire({
            title: "Confirm Vendor Status",
            text: `Set vendor status to "${selectedStatus}"?`,
            icon: "question",
            showCancelButton: true,
            confirmButtonColor: "#0d6efd",
            confirmButtonText: "Confirm"
        });

        if (!confirm.isConfirmed) return;

        try {
            const result = await fetch(`https://elcto-1.onrender.com/api/approval/${id}`, {
                method: "put",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ status: selectedStatus })
            });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    Swal.fire({
                        title: "Success!",
                        text: `Vendor status updated to ${selectedStatus}`,
                        icon: "success",
                        timer: 1500,
                        showConfirmButton: false
                    });
                    show6();
                } else {
                    Swal.fire("Error", "Vendor approval failed", "error");
                }
            }
        } catch (err) {
            Swal.fire("Error", "Network error approving vendor", "error");
        }
    };

    // Filtering logic
    // Orders
    const filteredOrders = order.filter(item => {
        const matchSearch = (item.OrderNo && String(item.OrderNo).toLowerCase().includes(orderSearch.toLowerCase())) ||
            (item.FirstName && item.FirstName.toLowerCase().includes(orderSearch.toLowerCase())) ||
            (item.LastName && item.LastName.toLowerCase().includes(orderSearch.toLowerCase()));
        const matchPayment = orderPaymentFilter === "all" || item.Payment === orderPaymentFilter;
        return matchSearch && matchPayment;
    });

    const paginatedOrders = filteredOrders.slice(
        (orderPage - 1) * orderPerPage,
        orderPage * orderPerPage
    );

    // Users
    const filteredUsers = d.filter(user => {
        const matchSearch = (user.FirstName && user.FirstName.toLowerCase().includes(userSearch.toLowerCase())) ||
            (user.LastName && user.LastName.toLowerCase().includes(userSearch.toLowerCase())) ||
            (user.Email && user.Email.toLowerCase().includes(userSearch.toLowerCase()));
        const matchType = userTypeFilter === "all" || user.UserType === userTypeFilter;
        const matchStatus = userStatusFilter === "all" || user.Status === userStatusFilter;
        return matchSearch && matchType && matchStatus;
    });

    const paginatedUsers = filteredUsers.slice(
        (userPage - 1) * userPerPage,
        userPage * userPerPage
    );

    // Vendors
    const filteredVendors = vdata.filter(vendor => {
        const matchSearch = (vendor.Name && vendor.Name.toLowerCase().includes(vendorSearch.toLowerCase())) ||
            (vendor.Email && vendor.Email.toLowerCase().includes(vendorSearch.toLowerCase())) ||
            (vendor.Phone && vendor.Phone.toLowerCase().includes(vendorSearch.toLowerCase()));
        const matchStatus = vendorStatusFilter === "all" || vendor.Status === vendorStatusFilter;
        return matchSearch && matchStatus;
    });

    const paginatedVendors = filteredVendors.slice(
        (vendorPage - 1) * vendorPerPage,
        vendorPage * vendorPerPage
    );

    const bardata = {
        labels: ["UserData"],
        datasets: [
            {
                label: "Users",
                data: [users],
                backgroundColor: "rgba(13,110,253,0.75)",
                borderRadius: 6,
                barThickness: 45
            },
            {
                label: "Admin",
                data: [totaladmin],
                backgroundColor: "rgba(220, 53, 69, 0.75)",
                borderRadius: 6,
                barThickness: 45
            }
        ]
    };

    const piedata = {
        labels: ["Total Orders", "Cash On Delivery", "Credit Card"],
        datasets: [
            {
                label: "Orders Breakdown",
                data: [totalorder, ondelivery, bycredit],
                backgroundColor: [
                    '#0d6efd',
                    '#198754',
                    '#ffc107'
                ],
            }
        ]
    };

    const options = {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
            legend: {
                position: 'top',
            }
        }
    };

    return (
        <>
            {utype === "admin" ? (
                <div className="container-fluid py-3">
                    <div className="row g-4">
                        {/* Sidebar Navigation */}
                        <div className="col-lg-3 col-md-4">
                            <div className="card border-0 shadow-sm sticky-top" style={{ top: "80px", zIndex: 10 }}>
                                <div className="card-body p-4">
                                    <div className="d-flex align-items-center gap-2 mb-4">
                                        <i className="bi bi-speedometer2 fs-4 text-primary"></i>
                                        <h4 className="fw-bold mb-0">Admin Dashboard</h4>
                                    </div>
                                    <ul className="nav flex-column gap-2 nav-pills">
                                        <li className="nav-item">
                                            <a href="#stats" className="nav-link text-dark fw-semibold d-flex align-items-center gap-2 py-2">
                                                <i className="bi bi-grid-fill text-primary"></i> Overview & Stats
                                            </a>
                                        </li>
                                        <li className="nav-item">
                                            <a href="#orders" className="nav-link text-dark fw-semibold d-flex align-items-center gap-2 py-2">
                                                <i className="bi bi-box-seam-fill text-warning"></i> Orders ({totalorder})
                                            </a>
                                        </li>
                                        <li className="nav-item">
                                            <a href="#users" className="nav-link text-dark fw-semibold d-flex align-items-center gap-2 py-2">
                                                <i className="bi bi-people-fill text-info"></i> Users ({users})
                                            </a>
                                        </li>
                                        <li className="nav-item">
                                            <a href="#vendors" className="nav-link text-dark fw-semibold d-flex align-items-center gap-2 py-2">
                                                <i className="bi bi-shop text-success"></i> Vendors ({vdata.length})
                                            </a>
                                        </li>
                                    </ul>
                                </div>
                            </div>
                        </div>

                        {/* Main Content Area */}
                        <div className="col-lg-9 col-md-8">
                            {/* Summary Cards */}
                            <div className="row g-3 mb-4" id="stats">
                                <div className="col-xl-3 col-sm-6">
                                    <div className="card border-0 shadow-sm text-white h-100" style={{ background: "linear-gradient(135deg, #0d6efd 0%, #0a58ca 100%)" }}>
                                        <div className="card-body p-3 d-flex justify-content-between align-items-center">
                                            <div>
                                                <span className="text-white-50 small fw-bold">CATEGORIES</span>
                                                <h3 className="fw-bold mb-0">{length}</h3>
                                            </div>
                                            <i className="bi bi-folder-fill fs-1 text-white-50"></i>
                                        </div>
                                    </div>
                                </div>

                                <div className="col-xl-3 col-sm-6">
                                    <div className="card border-0 shadow-sm text-white h-100" style={{ background: "linear-gradient(135deg, #198754 0%, #146c43 100%)" }}>
                                        <div className="card-body p-3 d-flex justify-content-between align-items-center">
                                            <div>
                                                <span className="text-white-50 small fw-bold">PRODUCTS</span>
                                                <h3 className="fw-bold mb-0">{prolength}</h3>
                                            </div>
                                            <i className="bi bi-cart-fill fs-1 text-white-50"></i>
                                        </div>
                                    </div>
                                </div>

                                <div className="col-xl-3 col-sm-6">
                                    <div className="card border-0 shadow-sm text-white h-100" style={{ background: "linear-gradient(135deg, #ffc107 0%, #d39e00 100%)" }}>
                                        <div className="card-body p-3 d-flex justify-content-between align-items-center">
                                            <div>
                                                <span className="text-white-50 small fw-bold">USERS</span>
                                                <h3 className="fw-bold mb-0">{users}</h3>
                                            </div>
                                            <i className="bi bi-people-fill fs-1 text-white-50"></i>
                                        </div>
                                    </div>
                                </div>

                                <div className="col-xl-3 col-sm-6">
                                    <div className="card border-0 shadow-sm text-white h-100" style={{ background: "linear-gradient(135deg, #212529 0%, #343a40 100%)" }}>
                                        <div className="card-body p-3 d-flex justify-content-between align-items-center">
                                            <div>
                                                <span className="text-white-50 small fw-bold">BRANDS</span>
                                                <h3 className="fw-bold mb-0">{brand}</h3>
                                            </div>
                                            <i className="bi bi-tags-fill fs-1 text-white-50"></i>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Analytics Charts */}
                            <div className="row g-4 mb-4">
                                <div className="col-md-6">
                                    <div className="card border-0 shadow-sm h-100">
                                        <div className="card-header bg-white border-0 py-3">
                                            <h6 className="fw-bold mb-0 d-flex align-items-center gap-2">
                                                <i className="bi bi-bar-chart-fill text-primary"></i> User Distribution
                                            </h6>
                                        </div>
                                        <div className="card-body" style={{ minHeight: "300px" }}>
                                            <Bar data={bardata} options={options} />
                                        </div>
                                    </div>
                                </div>
                                <div className="col-md-6">
                                    <div className="card border-0 shadow-sm h-100">
                                        <div className="card-header bg-white border-0 py-3">
                                            <h6 className="fw-bold mb-0 d-flex align-items-center gap-2">
                                                <i className="bi bi-pie-chart-fill text-success"></i> Payment Method Analytics
                                            </h6>
                                        </div>
                                        <div className="card-body" style={{ minHeight: "300px" }}>
                                            <Pie data={piedata} options={options} />
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Monthly Sales Chart */}
                            <div className="card border-0 shadow-sm mb-5">
                                <div className="card-header bg-white border-0 py-3">
                                    <h6 className="fw-bold mb-0 d-flex align-items-center gap-2">
                                        <i className="bi bi-graph-up text-primary"></i> Monthly Sales Trends
                                    </h6>
                                </div>
                                <div className="card-body" style={{ minHeight: "300px" }}>
                                    <Line data={monthlyData} options={options} />
                                </div>
                            </div>

                            {/* SECTION: Orders List with Pagination */}
                            <div className="card border-0 shadow-sm mb-5" id="orders">
                                <div className="card-header bg-white py-3 d-flex flex-wrap justify-content-between align-items-center gap-2">
                                    <div className="d-flex align-items-center gap-2">
                                        <i className="bi bi-box-seam fs-5 text-primary"></i>
                                        <h5 className="mb-0 fw-bold">Customer Orders</h5>
                                        <span className="badge bg-primary rounded-pill">{filteredOrders.length}</span>
                                    </div>
                                </div>

                                <div className="card-body">
                                    {/* Order Search & Filters */}
                                    <div className="row g-3 mb-4">
                                        <div className="col-md-6">
                                            <div className="input-group">
                                                <span className="input-group-text bg-light border-end-0">
                                                    <i className="bi bi-search text-muted"></i>
                                                </span>
                                                <input
                                                    type="text"
                                                    className="form-control bg-light border-start-0"
                                                    placeholder="Search order # or customer name..."
                                                    value={orderSearch}
                                                    onChange={(e) => {
                                                        setOrderSearch(e.target.value);
                                                        setOrderPage(1);
                                                    }}
                                                />
                                                {orderSearch && (
                                                    <button className="btn btn-outline-secondary" onClick={() => setOrderSearch("")}>Clear</button>
                                                )}
                                            </div>
                                        </div>
                                        <div className="col-md-4">
                                            <select
                                                className="form-select"
                                                value={orderPaymentFilter}
                                                onChange={(e) => {
                                                    setOrderPaymentFilter(e.target.value);
                                                    setOrderPage(1);
                                                }}
                                            >
                                                <option value="all">All Payment Methods</option>
                                                <option value="Cash on Delivery">Cash on Delivery</option>
                                                <option value="Credit Card">Credit Card</option>
                                            </select>
                                        </div>
                                    </div>

                                    {/* Accordion Orders View */}
                                    {paginatedOrders.length > 0 ? (
                                        <div className="accordion" id="ordersAccordion">
                                            {paginatedOrders.map((ord) => (
                                                <div className="accordion-item mb-3 border rounded shadow-sm overflow-hidden" key={ord._id}>
                                                    <h2 className="accordion-header">
                                                        <button
                                                            className="accordion-button collapsed bg-white"
                                                            type="button"
                                                            data-bs-toggle="collapse"
                                                            data-bs-target={`#order${ord._id}`}
                                                        >
                                                            <div className="w-100 d-flex flex-wrap justify-content-between align-items-center pe-3">
                                                                <div>
                                                                    <strong className="text-primary">Order #{ord.OrderNo || ord._id.slice(-6)}</strong>
                                                                    <span className="ms-3 text-dark">{ord.FirstName} {ord.LastName}</span>
                                                                </div>
                                                                <div>
                                                                    <span className={`badge me-2 ${ord.Payment === 'Credit Card' ? 'bg-info' : 'bg-secondary'}`}>
                                                                        {ord.Payment}
                                                                    </span>
                                                                </div>
                                                            </div>
                                                        </button>
                                                    </h2>
                                                    <div
                                                        id={`order${ord._id}`}
                                                        className="accordion-collapse collapse"
                                                        data-bs-parent="#ordersAccordion"
                                                    >
                                                        <div className="accordion-body bg-light">
                                                            <div className="row mb-3">
                                                                <div className="col-md-6">
                                                                    <p className="mb-1"><strong>Customer:</strong> {ord.FirstName} {ord.LastName}</p>
                                                                    <p className="mb-1"><strong>Payment:</strong> {ord.Payment}</p>
                                                                </div>
                                                            </div>
                                                            <h6 className="fw-bold mb-2">Order Items:</h6>
                                                            <div className="list-group">
                                                                {ord.Order && ord.Order.map((item, idx) => (
                                                                    <div key={idx} className="list-group-item d-flex align-items-center justify-content-between gap-3">
                                                                        <div className="d-flex align-items-center gap-3">
                                                                            <img
                                                                                src={item.Img || "https://via.placeholder.com/50"}
                                                                                alt={item.ProductName}
                                                                                width="50"
                                                                                height="50"
                                                                                className="rounded object-fit-cover"
                                                                                onError={(e) => { e.target.src = "https://via.placeholder.com/50"; }}
                                                                            />
                                                                            <div>
                                                                                <div className="fw-semibold">{item.ProductName}</div>
                                                                                <small className="text-muted">
                                                                                    Qty: {item.Quantity} × ₹{item.Price}
                                                                                </small>
                                                                            </div>
                                                                        </div>
                                                                        <strong className="text-success">₹{item.Quantity * item.Price}</strong>
                                                                    </div>
                                                                ))}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    ) : (
                                        <div className="text-center py-4 text-muted">
                                            <i className="bi bi-box-seam fs-1 d-block mb-2 text-secondary"></i>
                                            No orders match your search criteria.
                                        </div>
                                    )}

                                    {/* Orders Pagination Controls */}
                                    <Pagination
                                        totalItems={filteredOrders.length}
                                        itemsPerPage={orderPerPage}
                                        currentPage={orderPage}
                                        onPageChange={setOrderPage}
                                        onPerPageChange={setOrderPerPage}
                                    />
                                </div>
                            </div>

                            {/* SECTION: Users List with Pagination */}
                            <div className="card border-0 shadow-sm mb-5" id="users">
                                <div className="card-header bg-white py-3 d-flex flex-wrap justify-content-between align-items-center gap-2">
                                    <div className="d-flex align-items-center gap-2">
                                        <i className="bi bi-people fs-5 text-info"></i>
                                        <h5 className="mb-0 fw-bold">Registered Users</h5>
                                        <span className="badge bg-info rounded-pill">{filteredUsers.length}</span>
                                    </div>
                                </div>

                                <div className="card-body">
                                    {/* User Search & Filters */}
                                    <div className="row g-3 mb-4">
                                        <div className="col-md-5">
                                            <div className="input-group">
                                                <span className="input-group-text bg-light border-end-0">
                                                    <i className="bi bi-search text-muted"></i>
                                                </span>
                                                <input
                                                    type="text"
                                                    className="form-control bg-light border-start-0"
                                                    placeholder="Search user name or email..."
                                                    value={userSearch}
                                                    onChange={(e) => {
                                                        setUserSearch(e.target.value);
                                                        setUserPage(1);
                                                    }}
                                                />
                                                {userSearch && (
                                                    <button className="btn btn-outline-secondary" onClick={() => setUserSearch("")}>Clear</button>
                                                )}
                                            </div>
                                        </div>
                                        <div className="col-md-3">
                                            <select
                                                className="form-select"
                                                value={userTypeFilter}
                                                onChange={(e) => {
                                                    setUserTypeFilter(e.target.value);
                                                    setUserPage(1);
                                                }}
                                            >
                                                <option value="all">All User Types</option>
                                                <option value="admin">Admin</option>
                                                <option value="user">User</option>
                                            </select>
                                        </div>
                                        <div className="col-md-4">
                                            <select
                                                className="form-select"
                                                value={userStatusFilter}
                                                onChange={(e) => {
                                                    setUserStatusFilter(e.target.value);
                                                    setUserPage(1);
                                                }}
                                            >
                                                <option value="all">All Statuses</option>
                                                <option value="Active">Active</option>
                                                <option value="Inactive">Inactive</option>
                                            </select>
                                        </div>
                                    </div>

                                    {/* Users Table */}
                                    <div className="table-responsive">
                                        <table className="table table-hover align-middle mb-0">
                                            <thead className="table-light">
                                                <tr>
                                                    <th>User</th>
                                                    <th>Email</th>
                                                    <th>Status</th>
                                                    <th>Role</th>
                                                    <th>Modify Role</th>
                                                    <th>Modify Status</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {paginatedUsers.length > 0 ? (
                                                    paginatedUsers.map((a) => (
                                                        <tr key={a._id}>
                                                            <td>
                                                                <div className="d-flex align-items-center gap-2">
                                                                    <div
                                                                        className="rounded-circle bg-primary text-white d-flex align-items-center justify-content-center fw-bold"
                                                                        style={{ width: "38px", height: "38px", fontSize: "14px" }}
                                                                    >
                                                                        {a.FirstName ? a.FirstName.charAt(0).toUpperCase() : "U"}
                                                                    </div>
                                                                    <div>
                                                                        <div className="fw-semibold">{a.FirstName} {a.LastName}</div>
                                                                        <small className="text-muted font-monospace">{a._id.slice(-6)}</small>
                                                                    </div>
                                                                </div>
                                                            </td>
                                                            <td>{a.Email}</td>
                                                            <td>
                                                                {a.Status === "Active" ? (
                                                                    <span className="badge bg-success-subtle text-success border border-success-subtle px-2 py-1">
                                                                        <i className="bi bi-circle-fill fs-6 me-1 small" style={{ fontSize: "8px" }}></i>
                                                                        Active
                                                                    </span>
                                                                ) : (
                                                                    <span className="badge bg-danger-subtle text-danger border border-danger-subtle px-2 py-1">
                                                                        <i className="bi bi-circle-fill fs-6 me-1 small" style={{ fontSize: "8px" }}></i>
                                                                        Inactive
                                                                    </span>
                                                                )}
                                                            </td>
                                                            <td>
                                                                <span className={`badge ${a.UserType === 'admin' ? 'bg-danger' : 'bg-secondary'}`}>
                                                                    {a.UserType}
                                                                </span>
                                                            </td>
                                                            <td>
                                                                <div className="d-flex align-items-center gap-1">
                                                                    <select
                                                                        className="form-select form-select-sm"
                                                                        style={{ width: "100px" }}
                                                                        value={pendingRoles[a._id] || ""}
                                                                        onChange={(e) => setPendingRoles({ ...pendingRoles, [a._id]: e.target.value })}
                                                                    >
                                                                        <option value="">Select</option>
                                                                        <option value="admin">Admin</option>
                                                                        <option value="user">User</option>
                                                                    </select>
                                                                    <button
                                                                        className="btn btn-sm btn-outline-primary"
                                                                        onClick={() => handleUserRoleChange(a._id)}
                                                                    >
                                                                        Save
                                                                    </button>
                                                                </div>
                                                            </td>
                                                            <td>
                                                                <div className="d-flex align-items-center gap-1">
                                                                    <select
                                                                        className="form-select form-select-sm"
                                                                        style={{ width: "100px" }}
                                                                        value={pendingStatuses[a._id] || ""}
                                                                        onChange={(e) => setPendingStatuses({ ...pendingStatuses, [a._id]: e.target.value })}
                                                                    >
                                                                        <option value="">Select</option>
                                                                        <option value="Active">Active</option>
                                                                        <option value="Inactive">Inactive</option>
                                                                    </select>
                                                                    <button
                                                                        className="btn btn-sm btn-outline-success"
                                                                        onClick={() => handleUserStatusChange(a._id)}
                                                                    >
                                                                        Save
                                                                    </button>
                                                                </div>
                                                            </td>
                                                        </tr>
                                                    ))
                                                ) : (
                                                    <tr>
                                                        <td colSpan="6" className="text-center py-4 text-muted">
                                                            No users found matching filter.
                                                        </td>
                                                    </tr>
                                                )}
                                            </tbody>
                                        </table>
                                    </div>

                                    {/* Users Pagination Controls */}
                                    <Pagination
                                        totalItems={filteredUsers.length}
                                        itemsPerPage={userPerPage}
                                        currentPage={userPage}
                                        onPageChange={setUserPage}
                                        onPerPageChange={setUserPerPage}
                                    />
                                </div>
                            </div>

                            {/* SECTION: Vendor List with Pagination */}
                            <div className="card border-0 shadow-sm mb-5" id="vendors">
                                <div className="card-header bg-white py-3 d-flex flex-wrap justify-content-between align-items-center gap-2">
                                    <div className="d-flex align-items-center gap-2">
                                        <i className="bi bi-shop fs-5 text-success"></i>
                                        <h5 className="mb-0 fw-bold">Vendor Applications</h5>
                                        <span className="badge bg-success rounded-pill">{filteredVendors.length}</span>
                                    </div>
                                </div>

                                <div className="card-body">
                                    {/* Vendor Search & Filters */}
                                    <div className="row g-3 mb-4">
                                        <div className="col-md-6">
                                            <div className="input-group">
                                                <span className="input-group-text bg-light border-end-0">
                                                    <i className="bi bi-search text-muted"></i>
                                                </span>
                                                <input
                                                    type="text"
                                                    className="form-control bg-light border-start-0"
                                                    placeholder="Search vendor name, email, or phone..."
                                                    value={vendorSearch}
                                                    onChange={(e) => {
                                                        setVendorSearch(e.target.value);
                                                        setVendorPage(1);
                                                    }}
                                                />
                                                {vendorSearch && (
                                                    <button className="btn btn-outline-secondary" onClick={() => setVendorSearch("")}>Clear</button>
                                                )}
                                            </div>
                                        </div>
                                        <div className="col-md-4">
                                            <select
                                                className="form-select"
                                                value={vendorStatusFilter}
                                                onChange={(e) => {
                                                    setVendorStatusFilter(e.target.value);
                                                    setVendorPage(1);
                                                }}
                                            >
                                                <option value="all">All Vendor Statuses</option>
                                                <option value="Pending">Pending</option>
                                                <option value="Accept">Accept</option>
                                                <option value="Reject">Reject</option>
                                            </select>
                                        </div>
                                    </div>

                                    {/* Vendor Table */}
                                    <div className="table-responsive">
                                        <table className="table table-hover align-middle mb-0">
                                            <thead className="table-light">
                                                <tr>
                                                    <th>Vendor Name</th>
                                                    <th>Email</th>
                                                    <th>Phone</th>
                                                    <th>Current Status</th>
                                                    <th>Action</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {paginatedVendors.length > 0 ? (
                                                    paginatedVendors.map((a) => (
                                                        <tr key={a._id}>
                                                            <td className="fw-semibold">{a.Name}</td>
                                                            <td>{a.Email}</td>
                                                            <td>{a.Phone || "N/A"}</td>
                                                            <td>
                                                                <span className={`badge ${a.Status === 'Accept' ? 'bg-success' : a.Status === 'Pending' ? 'bg-warning text-dark' : 'bg-secondary'}`}>
                                                                    {a.Status || 'Pending'}
                                                                </span>
                                                            </td>
                                                            <td>
                                                                <div className="d-flex align-items-center gap-2">
                                                                    <select
                                                                        className="form-select form-select-sm"
                                                                        style={{ width: "120px" }}
                                                                        value={pendingVendorStatuses[a._id] || ""}
                                                                        onChange={(e) => setPendingVendorStatuses({ ...pendingVendorStatuses, [a._id]: e.target.value })}
                                                                    >
                                                                        <option value="">Select</option>
                                                                        <option value="Accept">Accept</option>
                                                                        <option value="Pending">Pending</option>
                                                                        <option value="Reject">Reject</option>
                                                                    </select>
                                                                    <button
                                                                        className="btn btn-sm btn-primary"
                                                                        onClick={() => approval(a._id)}
                                                                    >
                                                                        Update
                                                                    </button>
                                                                </div>
                                                            </td>
                                                        </tr>
                                                    ))
                                                ) : (
                                                    <tr>
                                                        <td colSpan="5" className="text-center py-4 text-muted">
                                                            No vendor applications found.
                                                        </td>
                                                    </tr>
                                                )}
                                            </tbody>
                                        </table>
                                    </div>

                                    {/* Vendor Pagination Controls */}
                                    <Pagination
                                        totalItems={filteredVendors.length}
                                        itemsPerPage={vendorPerPage}
                                        currentPage={vendorPage}
                                        onPageChange={setVendorPage}
                                        onPerPageChange={setVendorPerPage}
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            ) : (
                navigate("/")
            )}
        </>
    );
};
